#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n, a[512];
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }
    long long out[512], p = 1;
    for (int i = 0; i < n; i++) {
        out[i] = p;
        p *= a[i];
    }
    p = 1;
    for (int i = n - 1; i >= 0; i--) {
        out[i] *= p;
        p *= a[i];
    }
    if (!n)
        puts("EMPTY");
    for (int i = 0; i < n; i++)
        printf("%s%lld", i ? " " : "", out[i]);
    if (n)
        puts("");
    return 0;
}

