#include <ctype.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int imin(int a, int b) {
    return a < b ? a : b;
}
int imax(int a, int b) {
    return a > b ? a : b;
}

int main(void) {
    int n, a[512];
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }
    int left[512], right = 0;
    long long ans = 0;
    for (int i = 0; i < n; i++)
        left[i] = i ? imax(left[i - 1], a[i]) : a[i];
    for (int i = n - 1; i >= 0; i--) {
        right = imax(right, a[i]);
        ans += imin(left[i], right) - a[i];
    }
    printf("%lld\n", ans);
    return 0;
}

