#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int cmp(const void *x, const void *y) {
    int a = *(const int *)x;
    int b = *(const int *)y;
    return (a > b) - (a < b);
}
int imax(int a, int b) {
    return a > b ? a : b;
}

int main(void) {
    int n, a[512];
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }
    qsort(a, n, sizeof *a, cmp);
    int best = 0, run = 0;
    for (int i = 0; i < n; i++) {
        if (i && a[i] == a[i - 1])
            continue;
        run = (i && a[i] == a[i - 1] + 1) ? run + 1 : 1;
        best = imax(best, run);
    }
    printf("%d\n", best);
    return 0;
}

