void pv(const int *a, int n) {
    if (n == 0) {
        puts("EMPTY");
        return;
    }
    for (int i = 0; i < n; ++i) {
        printf("%s%d", i ? " " : "", a[i]);
    }
    puts("");
}

int main(void) {
    int r, c, a[32][32];
    scanf("%d%d", &r, &c);
    for (int i = 0; i < r; i++)
        for (int j = 0; j < c; j++)
            scanf("%d", &a[i][j]);
    int t = 0, b = r - 1, l = 0, h = c - 1, out[1024], m = 0;
    while (t <= b && l <= h) {
        for (int j = l; j <= h; j++)
            out[m++] = a[t][j];
        t++;
        for (int i = t; i <= b; i++)
            out[m++] = a[i][h];
        h--;
        if (t <= b) {
            for (int j = h; j >= l; j--)
                out[m++] = a[b][j];
            b--;
        }
        if (l <= h) {
            for (int i = b; i >= t; i--)
                out[m++] = a[i][l];
            l++;
        }
    }
    pv(out, m);
    return 0;
}

