#include <string.h>

void pv(const int *a, int n) {
    if (n == 0) {
        puts("EMPTY");
        return;
    }
    for (int i = 0; i < n; ++i) {
        printf("%s%d", i ? " " : "", a[i]);
    }
    puts("");
}
int n, w[32][32];

int main(void) {
    int m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++) {
        int u, v, cost;
        scanf("%d%d%d", &u, &v, &cost);
        w[u][v] = cost;
        w[v][u] = cost;
    }
    int d[32], used[32] = {0};
    for (int i = 0; i < n; i++)
        d[i] = 1000000;
    d[0] = 0;
    for (int step = 0; step < n; step++) {
        int u = -1;
        for (int i = 0; i < n; i++)
            if (!used[i] && (u < 0 || d[i] < d[u]))
                u = i;
        if (u < 0 || d[u] == 1000000)
            break;
        used[u] = 1;
        for (int v = 0; v < n; v++)
            if (w[u][v] && d[u] + w[u][v] < d[v])
                d[v] = d[u] + w[u][v];
    }
    for (int i = 0; i < n; i++)
        if (d[i] == 1000000)
            d[i] = -1;
    pv(d, n);
    return 0;
}

