#include <ctype.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;
Node *reverse(Node *h) {
    Node *prev = NULL;
    while (h) {
        Node *next = h->next;
        h->next = prev;
        prev = h;
        h = next;
    }
    return prev;
}

int main(void) {
    int n;
    scanf("%d", &n);
    Node *head = NULL, **tail = &head;
    for (int i = 0; i < n; i++) {
        Node *p = malloc(sizeof *p);
        if (!p)
            return 1;
        scanf("%d", &p->value);
        p->next = NULL;
        *tail = p;
        tail = &p->next;
    }
    head = reverse(head);
    if (!head)
        puts("EMPTY");
    int first = 1;
    for (Node *p = head; p; p = p->next) {
        printf("%s%d", first ? "" : " ", p->value);
        first = 0;
    }
    if (head)
        puts("");
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

