int size, col[12], diag1[24], diag2[24];
long long answer;
void place(int row) {
    if (row == size) {
        answer++;
        return;
    }
    for (int c = 0; c < size; c++) {
        int x = row + c, y = row - c + size;
        if (!col[c] && !diag1[x] && !diag2[y]) {
            col[c] = diag1[x] = diag2[y] = 1;
            place(row + 1);
            col[c] = diag1[x] = diag2[y] = 0;
        }
    }
}

int main(void) {
    long long a;
    scanf("%lld", &a);
    size = (int)a;
    place(0);
    printf("%lld\n", answer);
    return 0;
}

