int values[12], size, threshold;
long long total;
void arrange(int mask, int previous, int depth) {
    if (depth == size) {
        total++;
        return;
    }
    for (int i = 0; i < size; i++)
        if (!(mask & (1 << i)) &&
            (depth == 0 || abs(values[i] - values[previous]) >= threshold))
            arrange(mask | (1 << i), i, depth + 1);
}

int main(void) {
    scanf("%d%d", &size, &threshold);
    for (int i = 0; i < size; i++)
        scanf("%d", &values[i]);
    arrange(0, 0, 0);
    printf("%lld\n", total);
    return 0;
}

