#include <ctype.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n, a[512];
    int k;
    scanf("%d%d", &n, &k);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }
    int total = 0;
    for (int i = 0; i < n; i++)
        total += a[i];
    if (total % k) {
        puts("NO");
        return 0;
    }
    int target = total / k;
    int dp[1024];
    for (int mask = 0; mask < (1 << n); mask++)
        dp[mask] = -1;
    dp[0] = 0;
    for (int mask = 0; mask < (1 << n); mask++)
        if (dp[mask] >= 0)
            for (int i = 0; i < n; i++)
                if (!(mask & (1 << i)) && dp[mask] + a[i] <= target)
                    dp[mask | (1 << i)] = (dp[mask] + a[i]) % target;
    puts(dp[(1 << n) - 1] == 0 ? "YES" : "NO");
    return 0;
}

