    int n = (int)strlen(s);
    (void)n;
    int ans = 0;
    for (int i = 1; i <= 3 && i < n; i++)
        for (int j = i + 1; j <= i + 3 && j < n; j++)
            for (int k = j + 1; k <= j + 3 && k < n; k++) {
                int cuts[5] = {0, i, j, k, n}, ok = 1;
                for (int p = 0; p < 4; p++) {
                    int l = cuts[p], r = cuts[p + 1], value = 0;
                    if (r - l > 3 || (r - l > 1 && s[l] == '0'))
                        ok = 0;
                    for (int t = l; t < r; t++)
                        value = value * 10 + s[t] - '0';
                    if (value > 255)
                        ok = 0;
                }
                ans += ok;
            }
    printf("%d\n", ans);
    return 0;
}

