#include <ctype.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int rows, cols, visited[4][4];
long long answer;
void search(int x, int y) {
    if (x == rows - 1 && y == cols - 1) {
        answer++;
        return;
    }
    visited[x][y] = 1;
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
    for (int d = 0; d < 4; d++) {
        int a = x + dx[d], b = y + dy[d];
        if (a >= 0 && a < rows && b >= 0 && b < cols && !visited[a][b])
            search(a, b);
    }
    visited[x][y] = 0;
}

int main(void) {
    long long a, b;
    scanf("%lld %lld", &a, &b);
    rows = (int)a;
    cols = (int)b;
    search(0, 0);
    printf("%lld\n", answer);
    return 0;
}

